    40  buffer_init(struct buffer *b, int fd, const struct stat *st, const void *data,
    41      size_t len)
    42  {
    43          b->fd = fd;
    44          if (st)
    45                  memcpy(&b->st, st, sizeof(b->st));
    46          else if (b->fd == -1 || fstat(b->fd, &b->st) == -1)
    47                  memset(&b->st, 0, sizeof(b->st));
    48          b->fbuf = data;
    49          b->flen = len;
    50          b->eoff = 0;
    51          b->ebuf = NULL;
    52          b->elen = 0;
    53  }
